    /// <summary>One-shot CH02 greybox builder. It appends, rather than replaces, Build Settings.</summary>
    public static class AtchafalayaBuilder
    {
        const string Root="Assets/_Game", ScenePath=Root+"/Scenes/SCN_Atchafalaya_Slice.unity";
        static readonly List<HuntInteractable> Items=new();
        static TMP_FontAsset Font; static HuntSession Session;
        static Material Mud,Wood,Iron,Concrete,Water,Yellow,Paper,Skin,Leather;
        [MenuItem("Before Jericho/Create Atchafalaya Slice")]
        public static void Create()
        {
            if(File.Exists(ScenePath)) throw new System.InvalidOperationException("CH02 scene already exists. Do not overwrite it; remove only generated CH02 assets before a rebuild.");
            if(EditorSceneManager.GetActiveScene().isDirty) throw new System.InvalidOperationException("Save the active scene before generating CH02.");
            foreach(string folder in new[]{"Scenes","Data/Atchafalaya","Art/Materials/Atchafalaya"}) Directory.CreateDirectory(Root+"/"+folder);
            AssetDatabase.Refresh(); Font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/TextMesh Pro/Resources/Fonts & Materials/LiberationSans SDF.asset");
            if(!Font) throw new System.InvalidOperationException("TMP Essential Resources are required.");
            var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single); Items.Clear(); Materials();
            Ground(); Roadside(); Investigation(); PumpAndCrawl();
            var points=BuildPoints(); var door=IronDoor(); var final=Generator(); var rawhead=Rawhead(points);
            var definition=ScriptableObject.CreateInstance<HuntDefinition>(); definition.name="SO_AtchafalayaHunt"; AssetDatabase.CreateAsset(definition,Root+"/Data/Atchafalaya/SO_AtchafalayaHunt.asset");
            Session=new GameObject("Hunt Session").AddComponent<HuntSession>(); Session.definition=definition; Session.sound=Session.gameObject.AddComponent<HuntAudio>();
            rawhead.Configure(Session,rawhead.transform.Find("Rawhead silhouette"),rawhead.GetComponent<CharacterController>());
            var chapter=Session.gameObject.AddComponent<AtchafalayaChapter>(); chapter.Configure(Session,rawhead,points.arrival,points.chaseCheckpoint,points.prepCheckpoint,points.finalCheckpoint,points.chaseSpawn,points.finalSpawn,final.water,door.closed,final.red); chapter.SetEscapeBoundary(points.boundary);
            Player(); Hud(); Session.items=Items.ToArray(); Atmosphere();
            HdrpAuthoring.FinishScene("SCN_Atchafalaya_Slice", false);
            EditorSceneManager.SaveScene(scene,ScenePath); var build=new List<EditorBuildSettingsScene>(EditorBuildSettings.scenes); if(!build.Exists(s=>s.path==ScenePath)) build.Add(new EditorBuildSettingsScene(ScenePath,true)); EditorBuildSettings.scenes=build.ToArray(); AssetDatabase.SaveAssets();
            Debug.Log("BEFORE JERICHO: Created CH02 Atchafalaya with eight compact zones and "+Items.Count+" interactions.");
        }
        static void Materials()
        { Mud=Mat("CH02 Mud",new Color(.12f,.10f,.06f)); Wood=Mat("CH02 Cypress",new Color(.16f,.09f,.04f)); Iron=Mat("CH02 Iron",new Color(.10f,.13f,.13f),.5f); Concrete=Mat("CH02 Concrete",new Color(.24f,.29f,.28f),.3f); Water=Mat("CH02 Water",new Color(.04f,.16f,.18f),.7f,new Color(.01f,.06f,.07f)); Yellow=Mat("CH02 Warning",new Color(.78f,.48f,.06f),.2f,new Color(.2f,.1f,.01f)); Paper=Mat("CH02 Paper",new Color(.68f,.61f,.43f)); Skin=Mat("CH02 Skin",new Color(.43f,.28f,.18f)); Leather=Mat("CH02 Leather",new Color(.08f,.05f,.03f)); }
        static void Ground()
        { B("Belle Rive ground",new Vector3(0,-.3f,55),new Vector3(30,.5f,124),Mud); B("West boundary",new Vector3(-15,2,55),new Vector3(.5f,4,124),Concrete); B("East boundary",new Vector3(15,2,55),new Vector3(.5f,4,124),Concrete); B("South boundary",new Vector3(0,2,-7),new Vector3(30,4,.5f),Concrete); B("North boundary",new Vector3(0,2,117),new Vector3(30,4,.5f),Concrete); B("Roadside",new Vector3(0,-.04f,8),new Vector3(12,.18f,25),Concrete); B("Flooded Residential Strip",new Vector3(0,-.06f,33),new Vector3(24,.12f,24),Water); Sign("BELLE RIVE / HENDERSON ROAD",new Vector3(0,3,5),4,Yellow); }
        // Zone 1: gas station and return exit.
        static void Roadside()
        { B("Gas station slab",new Vector3(7,.04f,10),new Vector3(12,.2f,14),Concrete); B("Gas canopy",new Vector3(7,4.2f,10),new Vector3(12,.35f,14),Iron); for(int x=2;x<=12;x+=10)for(int z=5;z<=15;z+=10)B("Canopy post",new Vector3(x,2,z),new Vector3(.3f,4,.3f),Iron); B("Fuel pump",new Vector3(7,1,9),new Vector3(1.2f,2,.8f),Yellow); Sign("ROADHOUSE GAS",new Vector3(7,3.3f,3.1f),3,Yellow);
            var car=new GameObject("1967 Impala - Belle Rive exit blockout"); Part(car.transform,"Body",new Vector3(-2,.62f,2),new Vector3(2.05f,.65f,4.8f),Iron); Part(car.transform,"Cabin",new Vector3(-2,1.23f,1.7f),new Vector3(1.7f,.62f,2.25f),Leather); I(HuntItem.ChapterExit,"Leave Belle Rive / follow John's trail","The Impala is ready. Texas is west.",new Vector3(-2,1,4),Yellow); }
        // Zones 2–4: diner, raised-home clues, dock. All four evidence IDs are exact enum values.
        static void Investigation()
        { B("Small Diner floor",new Vector3(-7,.12f,15),new Vector3(12,.25f,13),Wood); Wall("Diner west",new Vector3(-13,2,15),new Vector3(.4f,4,13)); Wall("Diner north",new Vector3(-7,2,21.5f),new Vector3(12,4,.4f)); Wall("Diner south",new Vector3(-7,2,8.5f),new Vector3(12,4,.4f)); Sign("MARA'S DINER",new Vector3(-7,3.1f,8.25f),3,Yellow); B("Diner counter",new Vector3(-9,1,16),new Vector3(5,1.8f,.75f),Wood); Npc("Mara Boudreaux",HuntItem.Mara,"Ask Mara about the missing kids","Mara: Sheriff says gators. Gators don't open bedroom windows.\nDean: Yeah. They usually skip the breaking-and-entering part.",new Vector3(-6,1,15));
            B("Raised house platform",new Vector3(-8,1,29),new Vector3(9,.3f,10),Wood); for(int x=-11;x<=-5;x+=3)for(int z=26;z<=32;z+=3)B("House stilt",new Vector3(x,.45f,z),new Vector3(.25f,1.2f,.25f),Wood); Wall("House rear",new Vector3(-12.4f,2.6f,29),new Vector3(.35f,3.2f,10)); Wall("House south",new Vector3(-8,2.6f,24.1f),new Vector3(9,3.2f,.35f)); Wall("House north",new Vector3(-8,2.6f,33.9f),new Vector3(9,3.2f,.35f));
            for(int step=0;step<6;step++) B("Raised house access step "+step,new Vector3(-.7f-step*.5f,(.2f+step*.19f)*.5f,28.3f),new Vector3(.55f,.2f+step*.19f,2.4f),Wood);
            I(HuntItem.MudHandprints,"Inspect mud handprints","MUD HANDPRINTS: Too large for a child. The marks lead inward, though the bedroom window is locked.",new Vector3(-10,1.55f,28),Mud); B("Drain grate",new Vector3(9,.18f,29),new Vector3(1.1f,.12f,1.1f),Iron); I(HuntItem.HairTissue,"Collect hair and tissue","HAIR / TISSUE: Coarse hair caught below the house. Something physical uses the drain space.",new Vector3(9,.45f,29),Yellow,true);
            B("Dock / Swamp Edge",new Vector3(5,.15f,39),new Vector3(8,.25f,12),Wood); for(int x=2;x<=8;x+=3)for(int z=35;z<=43;z+=4)B("Dock post",new Vector3(x,.5f,z),new Vector3(.2f,1.2f,.2f),Wood); I(HuntItem.MissingReport,"Read old missing-child report","MISSING CHILD REPORT: Six years ago, children vanished from these raised homes. The pattern stopped without an arrest.",new Vector3(-6,1,39),Paper); I(HuntItem.ElectricalReport,"Read electrical accident report","ELECTRICAL ACCIDENT REPORT: A transformer surge struck the pump station. The disappearances stopped immediately after.",new Vector3(8,1,42),Paper); }
        // Zones 5–7: pump exterior/interior and a physically crawl-only four-metre route.
        static void PumpAndCrawl()
        { B("Pump Station Exterior",new Vector3(0,.1f,49),new Vector3(18,.25f,8),Concrete); Wall("Pump west shell",new Vector3(-9,2.2f,49),new Vector3(.5f,4.4f,8)); Wall("Pump east shell",new Vector3(9,2.2f,49),new Vector3(.5f,4.4f,8)); Wall("Pump back west partition",new Vector3(-5.55f,2.2f,52.8f),new Vector3(6.9f,4.4f,.5f)); Wall("Pump back east partition",new Vector3(5.55f,2.2f,52.8f),new Vector3(6.9f,4.4f,.5f)); B("Pump gantry",new Vector3(0,4.1f,49),new Vector3(18,.25f,8),Iron); Sign("BELLE RIVE FLOOD CONTROL",new Vector3(0,3.3f,45.1f),3,Yellow);
            B("Pipe Crawl floor",new Vector3(0,-.02f,63),new Vector3(4.2f,.12f,18),Concrete); Wall("Crawl left",new Vector3(-2.1f,.9f,63),new Vector3(.25f,1.8f,18)); Wall("Crawl right",new Vector3(2.1f,.9f,63),new Vector3(.25f,1.8f,18)); B("Crawl entry west partition",new Vector3(-8.55f,2,54),new Vector3(12.9f,4,.5f),Concrete); B("Crawl entry east partition",new Vector3(8.55f,2,54),new Vector3(12.9f,4,.5f),Concrete); B("Low pipe roof - crawl required",new Vector3(0,1.15f,61),new Vector3(4.2f,.25f,4.5f),Iron); for(int z=59;z<=63;z+=2)B("Low pressure pipe (visual)",new Vector3(0,.78f,z),new Vector3(3.7f,.26f,.26f),Iron).GetComponent<Collider>().enabled=false; I(HuntItem.CrawlTrace,"Examine fresh crawl traces","CRAWL TRACE: Fresh gouges in the mud. Something large crawled toward the iron door.",new Vector3(0,.28f,61),Yellow,true); Items[Items.Count-1].GetComponent<BoxCollider>().isTrigger=true; }
        // Zone 8: ordered controls, marked shallow water, safe switch ledge, Rawhead hunt and post-hunt receipt.
        static Final Generator()
        { B("Generator Chamber floor",new Vector3(0,.02f,94),new Vector3(24,.15f,42),Concrete); Wall("Generator west",new Vector3(-12,2.5f,94),new Vector3(.5f,5,42)); Wall("Generator east",new Vector3(12,2.5f,94),new Vector3(.5f,5,42)); Wall("Generator north",new Vector3(0,2.5f,115),new Vector3(24,5,.5f)); B("Generator roof",new Vector3(0,5,94),new Vector3(24,.25f,42),Iron);
            B("Fuel generator",new Vector3(-7,1.2f,82),new Vector3(3.3f,2.4f,2.4f),Iron); I(HuntItem.FuelValve,"Open fuel valve","FUEL VALVE: The generator has fuel. Open the valve, then reset the main breaker.",new Vector3(-7,1.1f,80.45f),Yellow); B("Main breaker cabinet",new Vector3(0,1.4f,85),new Vector3(1.4f,2.8f,.55f),Iron); I(HuntItem.MainBreaker,"Reset main breaker","MAIN BREAKER: Power reaches the generator. Start it and reroute the chamber circuit.",new Vector3(0,1.1f,84.4f),Yellow); B("Generator starter",new Vector3(7,1.3f,88),new Vector3(2.5f,2.6f,2.3f),Iron); I(HuntItem.GeneratorStart,"Start generator and reroute chamber","GENERATOR: The chamber circuit is live. Use the shallow water and isolated switch.",new Vector3(7,1.1f,86.55f),Yellow);
            Npc("Eli Mercer",HuntItem.Eli,"Ask Eli about the station","Eli: Power surged six years ago. Fried half the station. After that, the disappearances stopped.",new Vector3(8,1,86)); var water=B("Marked shallow-water kill zone",new Vector3(0,.15f,96),new Vector3(9,.3f,8),Water); var trigger=water.GetComponent<BoxCollider>(); trigger.isTrigger=true; for(int x=-4;x<=4;x+=2)B("Water hazard marker",new Vector3(x,.45f,92),new Vector3(.45f,.2f,.25f),Yellow); B("Safe switch ledge",new Vector3(7.5f,.65f,96),new Vector3(2.5f,1.3f,6),Concrete); I(HuntItem.VoltageSwitch,"Throw isolated voltage switch","VOLTAGE SWITCH: It discharges only if Rawhead stands in the marked water.",new Vector3(5.95f,1.3f,96),Yellow); I(HuntItem.JohnReceipt,"Take John's motel receipt","MOTEL RECEIPT: A room paid in cash. A note points west: Texas.",new Vector3(8,1,89),Paper); return new Final{water=trigger,red=Light("Emergency red light",new Vector3(0,4.4f,99),Color.red,.3f,20)}; }
        static Points BuildPoints()
        { var p=new Points{arrival=P("Arrival checkpoint",new Vector3(0,.1f,2)),chaseCheckpoint=P("Rawhead identified checkpoint",new Vector3(0,.1f,54)),prepCheckpoint=P("Iron door escape checkpoint",new Vector3(0,.1f,76)),finalCheckpoint=P("Water chamber checkpoint",new Vector3(0,.1f,94)),chaseSpawn=P("Rawhead chase spawn",new Vector3(0,.1f,57)),finalSpawn=P("Rawhead final spawn",new Vector3(0,.1f,102))}; p.route=new[]{P("Rawhead chase route 1",new Vector3(0,.1f,64)),P("Rawhead chase route 2",new Vector3(0,.1f,68)),P("Rawhead chase route 3",new Vector3(0,.1f,71))}; p.boundary=P("Iron door safe-side boundary",new Vector3(0,0,72)); p.boundary.forward=Vector3.forward; return p; }
        static Door IronDoor()
        { B("Iron door partition west",new Vector3(-8.55f,2,72),new Vector3(12.9f,4,.5f),Concrete); B("Iron door partition east",new Vector3(8.55f,2,72),new Vector3(12.9f,4,.5f),Concrete); B("Iron door frame left",new Vector3(-2.1f,1.5f,72),new Vector3(.3f,3,.4f),Iron); B("Iron door frame right",new Vector3(2.1f,1.5f,72),new Vector3(.3f,3,.4f),Iron); var closed=B("Iron door closed panel",new Vector3(0,1.5f,72),new Vector3(4,3,.25f),Iron); closed.SetActive(false); I(HuntItem.IronDoor,"Close iron door behind you","IRON DOOR: Cross to the safe side, then close it behind you.",new Vector3(0,1,72.7f),Iron); Items[Items.Count-1].GetComponent<BoxCollider>().isTrigger=true; return new Door{closed=closed}; }
        static RawheadHunt Rawhead(Points p)
        { var go=new GameObject("Rawhead"); go.layer=8; var cc=go.AddComponent<CharacterController>(); cc.height=1.75f; cc.radius=.42f; cc.center=Vector3.up*.875f; var visual=new GameObject("Rawhead silhouette").transform; visual.SetParent(go.transform,false); Part(visual,"Torso",new Vector3(0,.95f,0),new Vector3(.85f,1.4f,.5f),Skin); Part(visual,"Head",new Vector3(0,1.8f,.04f),new Vector3(.55f,.48f,.5f),Skin); Part(visual,"Hair",new Vector3(0,2.05f,-.08f),new Vector3(.68f,.2f,.56f),Mud); for(int x=-1;x<=1;x+=2)Part(visual,"Arm",new Vector3(x*.58f,1.1f,0),new Vector3(.22f,1.25f,.25f),Skin); var hunt=go.AddComponent<RawheadHunt>(); hunt.SetChaseRoute(p.route); go.transform.position=p.finalSpawn.position; return hunt; }
        static void Player()
        { var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/Prefabs/Actors/PF_Dean.prefab"); if(!prefab) throw new System.InvalidOperationException("PF_Dean.prefab is required; create the Prologue slice first."); var player=(GameObject)PrefabUtility.InstantiatePrefab(prefab); player.name="Dean Winchester"; player.transform.position=new Vector3(0,.1f,2); player.layer=2; var motor=player.GetComponent<HunterMotor>(); var combat=player.GetComponent<HunterCombat>(); motor.session=Session; combat.session=Session; combat.motor=motor; Session.player=motor;
            var camGo=new GameObject("OTS Camera"); var cam=camGo.AddComponent<Camera>(); camGo.tag="MainCamera"; camGo.AddComponent<AudioListener>(); cam.nearClipPlane=.05f; cam.farClipPlane=150; cam.clearFlags=CameraClearFlags.SolidColor; cam.backgroundColor=new Color(.04f,.07f,.075f); var shoulder=camGo.AddComponent<ShoulderCamera>(); shoulder.player=motor; shoulder.session=Session; shoulder.lens=cam; motor.view=shoulder; combat.view=shoulder; }
        static void Hud()
        { UIPrefabBuilder.PlaceInScene(Session); } // PF_HuntUI: the HTML-prototype UI (screens, HUD, options); keeps one EventSystem
        static void Atmosphere()
        { var moon=new GameObject("Bayou moon").AddComponent<Light>(); moon.type=LightType.Directional; moon.color=new Color(.38f,.52f,.55f); moon.intensity=.7f; moon.transform.rotation=Quaternion.Euler(45,-25,0); moon.shadows=LightShadows.Soft; RenderSettings.ambientMode=AmbientMode.Flat; RenderSettings.ambientLight=new Color(.07f,.11f,.1f); RenderSettings.fog=true; RenderSettings.fogColor=new Color(.055f,.1f,.09f); RenderSettings.fogMode=FogMode.ExponentialSquared; RenderSettings.fogDensity=.019f; }
        static Material Mat(string name,Color color,float smooth=0,Color? emission=null){var m=HdrpAuthoring.Lit(name, color, smooth, emission);AssetDatabase.CreateAsset(m,Root+"/Art/Materials/Atchafalaya/"+name+".mat");return m;}
        static GameObject B(string name,Vector3 pos,Vector3 scale,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.position=pos;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=mat;return g;} static void Wall(string n,Vector3 p,Vector3 s)=>B(n,p,s,Concrete); static Transform P(string n,Vector3 p){var t=new GameObject(n).transform;t.position=p;return t;} static Light Light(string n,Vector3 p,Color c,float i,float r){var l=new GameObject(n).AddComponent<Light>();l.transform.position=p;l.type=LightType.Point;l.color=c;l.intensity=i;l.range=r;return l;}
        static GameObject Part(Transform parent,string name,Vector3 p,Vector3 s,Material m){var g=B(name,p,s,m);g.transform.SetParent(parent,false);UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.layer=2;return g;} static void Sign(string text,Vector3 p,float size,Material mat){var g=new GameObject("Sign - "+text);g.transform.position=p;g.transform.rotation=Quaternion.identity;g.transform.localScale=Vector3.one*.09f;var t=g.AddComponent<TextMeshPro>();t.font=Font;t.text=text;t.fontSize=size*10;t.alignment=TextAlignmentOptions.Center;t.color=mat.color;t.textWrappingMode=TMPro.TextWrappingModes.NoWrap;t.rectTransform.sizeDelta=new Vector2(size*3,2);}
        static void Npc(string name,HuntItem kind,string label,string description,Vector3 p){var g=B(name,p,new Vector3(.58f,1.7f,.38f),Skin);var item=g.AddComponent<HuntInteractable>();item.kind=kind;item.label=label;item.description=description; Marker(g,item);} static void I(HuntItem kind,string label,string description,Vector3 p,Material m,bool light=false){var g=B("Interact - "+kind,p,new Vector3(.55f,.25f,.45f),m);var item=g.AddComponent<HuntInteractable>();item.kind=kind;item.label=label;item.description=description;item.needsLight=light;Marker(g,item);} static void Marker(GameObject owner,HuntInteractable item){var g=GameObject.CreatePrimitive(PrimitiveType.Sphere);g.name="Evidence marker";g.transform.SetParent(owner.transform);g.transform.localPosition=Vector3.up*.65f;g.transform.localScale=new Vector3(.18f,.4f,.22f);g.GetComponent<Renderer>().sharedMaterial=Yellow;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());item.marker=g.transform;Items.Add(item);}
        sealed class Final{public Collider water;public Light red;} sealed class Door{public GameObject closed;} sealed class Points{public Transform arrival,chaseCheckpoint,prepCheckpoint,finalCheckpoint,chaseSpawn,finalSpawn,boundary;public Transform[] route;}
    }
